export declare const UI_HTML = "<!DOCTYPE html>\n<html lang=\"zh\" class=\"dark\">\n<head>\n<meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Ark KB</title>\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<script>tailwind.config={darkMode:\"class\",theme:{extend:{colors:{surface:\"#0a0a0b\",card:\"#111113\",hover:\"#1a1a1d\",border:\"#2a2a2e\"}}}}</script>\n<style>\n@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&display=swap');\n*{font-family:'Inter',sans-serif;scrollbar-width:thin;scrollbar-color:#2a2a2e transparent}\nbody{background:#0a0a0b;color:#a1a1aa}\n.msg-user{background:linear-gradient(135deg,#6366f1,#8b5cf6)}\n.glass{background:rgba(255,255,255,.03);backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,.06)}\ninput,textarea,select{transition:all .15s}\ninput:focus,textarea:focus,select:focus{outline:none;border-color:#6366f1!important;box-shadow:0 0 0 1px #6366f133}\n</style>\n</head>\n<body class=\"flex h-screen overflow-hidden\">\n<aside class=\"w-56 flex flex-col p-5 border-r border-[#1a1a1d] shrink-0\">\n  <div class=\"flex items-center gap-2 mb-8\">\n    <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-indigo-500 to-purple-500 flex items-center justify-center text-white font-bold text-sm\">A</div>\n    <span class=\"font-semibold text-white text-sm\">Ark KB</span>\n  </div>\n  <nav class=\"flex flex-col gap-1 flex-1\">\n    <a href=\"#chat\" class=\"nav-link flex items-center gap-2.5 px-3 py-2 rounded-lg text-sm text-zinc-400 hover:text-zinc-200 hover:bg-white/[.03] transition-all no-underline\" onclick=\"switchTab('chat')\"><span class=\"text-base\">\uD83D\uDCAC</span>\u804A\u5929</a>\n    <a href=\"#config\" class=\"nav-link flex items-center gap-2.5 px-3 py-2 rounded-lg text-sm text-zinc-400 hover:text-zinc-200 hover:bg-white/[.03] transition-all no-underline\" onclick=\"switchTab('config')\"><span class=\"text-base\">\u2699\uFE0F</span>\u914D\u7F6E</a>\n    <a href=\"#logs\" class=\"nav-link flex items-center gap-2.5 px-3 py-2 rounded-lg text-sm text-zinc-400 hover:text-zinc-200 hover:bg-white/[.03] transition-all no-underline\" onclick=\"switchTab('logs')\"><span class=\"text-base\">\uD83D\uDCCB</span>\u65E5\u5FD7</a>\n  </nav>\n  <div class=\"text-xs text-zinc-500 mt-auto pt-4 border-t border-[#1a1a1d]\" id=\"kbStatus\"></div>\n</aside>\n\n<main class=\"flex-1 flex flex-col min-w-0\">\n  <header class=\"h-14 flex items-center gap-3 px-6 glass shrink-0\">\n    <select id=\"kbSelect\" onchange=\"onKbChange()\" class=\"h-9 px-4 bg-white/[.04] border border-[#2a2a2e] rounded-lg text-sm text-zinc-300 cursor-pointer\"><option value=\"all\">\uD83D\uDCDA \u5168\u90E8\u77E5\u8BC6\u5E93</option></select>\n    <button onclick=\"newKB()\" class=\"h-9 px-5 bg-indigo-500 hover:bg-indigo-600 text-white text-sm font-medium rounded-lg transition-colors\">\u65B0\u5EFA</button>\n    <button id=\"delKbBtn\" class=\"h-9 px-5 hidden text-sm text-red-400 hover:bg-red-400/10 rounded-lg transition-colors\" onclick=\"delKB()\">\u5220\u9664</button>\n  </header>\n\n  <section class=\"flex-1 flex overflow-hidden\">\n    <!-- Chat -->\n    <div id=\"chatPage\" class=\"flex-1 flex\">\n      <div class=\"flex-1 flex flex-col min-w-0\">\n        <div id=\"messages\" class=\"flex-1 overflow-y-auto px-6 py-5 flex flex-col gap-5\"></div>\n        <div class=\"p-4 glass flex gap-3 shrink-0 mx-4 mb-4 rounded-xl\">\n          <textarea id=\"chatInput\" rows=\"1\" placeholder=\"Ask anything about your knowledge base\u2026\" class=\"flex-1 py-3 px-0 bg-transparent text-sm text-zinc-200 placeholder:text-zinc-600 resize-none\" onkeydown=\"if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendMessage()}\"></textarea>\n          <button onclick=\"sendMessage()\" class=\"px-6 bg-indigo-500 hover:bg-indigo-600 text-white text-sm font-medium rounded-lg transition-colors shrink-0\">Send</button>\n        </div>\n      </div>\n      <aside class=\"w-72 border-l border-[#1a1a1d] flex flex-col shrink-0 overflow-hidden\">\n        <div class=\"px-5 py-4 text-sm font-medium text-zinc-300 flex justify-between items-center border-b border-[#1a1a1d]\">Files<span class=\"text-xs text-zinc-600 font-normal\" id=\"fileCount\"></span></div>\n        <div class=\"p-3\">\n          <div id=\"fileDrop\" class=\"flex flex-col items-center justify-center py-6 border-2 border-dashed border-[#2a2a2e] rounded-xl text-xs text-zinc-600 cursor-pointer hover:border-indigo-500/50 hover:text-indigo-400 transition-all\" onclick=\"this.querySelector('input').click()\">\n            <div class=\"text-2xl mb-1\">\uD83D\uDCE4</div>\n            <div>Drop files or click to upload</div>\n            <input type=\"file\" id=\"fileInput\" multiple hidden onchange=\"uploadFiles(this.files)\">\n          </div>\n        </div>\n        <div id=\"fileList\" class=\"flex-1 overflow-y-auto px-3\"></div>\n      </aside>\n    </div>\n\n    <!-- Config -->\n    <div id=\"configPage\" class=\"hidden flex-1 overflow-y-auto p-6\">\n      <div class=\"max-w-2xl flex flex-col gap-4\">\n        <div class=\"rounded-xl border border-[#1a1a1d] overflow-hidden\"><div class=\"px-5 py-3.5 bg-white/[.02] text-sm font-medium text-zinc-200 border-b border-[#1a1a1d]\">\uD83E\uDDE0 Embedding</div><div class=\"p-5\" id=\"cfgEmbedding\"></div></div>\n        <div class=\"rounded-xl border border-[#1a1a1d] overflow-hidden\"><div class=\"px-5 py-3.5 bg-white/[.02] text-sm font-medium text-zinc-200 border-b border-[#1a1a1d]\">\uD83D\uDD0D Reranker</div><div class=\"p-5\" id=\"cfgReranker\"></div></div>\n        <div class=\"rounded-xl border border-[#1a1a1d] overflow-hidden\"><div class=\"px-5 py-3.5 bg-white/[.02] text-sm font-medium text-zinc-200 border-b border-[#1a1a1d]\">\uD83D\uDC41 VLM</div><div class=\"p-5\" id=\"cfgVLM\"></div></div>\n        <div class=\"rounded-xl border border-[#1a1a1d] overflow-hidden\"><div class=\"px-5 py-3.5 bg-white/[.02] text-sm font-medium text-zinc-200 border-b border-[#1a1a1d]\">\uD83D\uDCAC LLM</div><div class=\"p-5\" id=\"cfgLLM\"></div></div>\n        <div class=\"flex justify-end pt-2\"><button onclick=\"saveConfig()\" class=\"px-8 py-2.5 bg-indigo-500 hover:bg-indigo-600 text-white text-sm font-medium rounded-lg transition-colors\">Save Changes</button></div>\n      </div>\n    </div>\n\n    <!-- Logs -->\n    <div id=\"logPage\" class=\"hidden flex-1 overflow-hidden p-6 flex flex-col gap-3\">\n      <div class=\"flex gap-3\"><button onclick=\"loadLogs()\" class=\"px-4 py-2 bg-white/[.04] border border-[#2a2a2e] text-zinc-400 hover:text-zinc-200 text-sm rounded-lg transition-colors\">Refresh</button></div>\n      <pre id=\"logContent\" class=\"flex-1 overflow-y-auto rounded-xl border border-[#1a1a1d] p-5 text-xs text-zinc-500 leading-relaxed font-mono\"></pre>\n    </div>\n  </section>\n</main>\n\n<script>\nlet currentKB=\"all\",kbs=[];\nfunction switchTab(t){document.querySelectorAll(\".nav-link\").forEach((a,i)=>{const active=a.getAttribute(\"href\")===\"#\"+t;a.style.background=active?\"rgba(255,255,255,.04)\":\"\";a.style.color=active?\"#e4e4e7\":\"#a1a1aa\"});document.getElementById(\"chatPage\").style.display=t===\"chat\"?\"flex\":\"none\";document.getElementById(\"configPage\").classList.toggle(\"hidden\",t!==\"config\");document.getElementById(\"logPage\").classList.toggle(\"hidden\",t!==\"logs\");if(t===\"config\")loadConfig();if(t===\"logs\")loadLogs()}\nasync function loadKBs(){try{const r=await fetch(\"/api/kb\");kbs=await r.json();const s=document.getElementById(\"kbSelect\");s.innerHTML='<option value=\"all\">\uD83D\uDCDA \u5168\u90E8\u77E5\u8BC6\u5E93</option>';kbs.forEach(k=>s.innerHTML+=`<option value=\"${k.name}\">\uD83D\uDCC2 ${k.name}<span class=\"text-zinc-600 ml-2\">${k.chunks||0} chunks</span></option>`);document.getElementById(\"delKbBtn\").classList.toggle(\"hidden\",currentKB===\"all\");document.getElementById(\"kbStatus\").innerHTML=`${kbs.length} knowledge bases<br>${kbs.reduce((a,k)=>a+(k.chunks||0),0)} indexed chunks`}catch(e){}}\nasync function newKB(){const n=prompt(\"Name:\");if(!n)return;try{await fetch(\"/api/kb\",{method:\"POST\",body:JSON.stringify({name:n}),headers:{\"Content-Type\":\"application/json\"}});await loadKBs()}catch(e){alert(e.message)}}\nasync function delKB(){if(!confirm(`Delete \"${currentKB}\"?`))return;try{await fetch(`/api/kb/${encodeURIComponent(currentKB)}`,{method:\"DELETE\"});currentKB=\"all\";document.getElementById(\"kbSelect\").value=\"all\";await loadKBs();await loadFiles()}catch(e){alert(e.message)}}\nfunction onKbChange(){currentKB=document.getElementById(\"kbSelect\").value;document.getElementById(\"delKbBtn\").classList.toggle(\"hidden\",currentKB===\"all\");loadFiles()}\nasync function loadFiles(){const l=document.getElementById(\"fileList\"),t=currentKB===\"all\"?(kbs[0]?.name||\"default\"):currentKB;if(!t){l.innerHTML=\"\";return}try{const r=await fetch(`/api/kb/${encodeURIComponent(t)}/files`),fs=await r.json();document.getElementById(\"fileCount\").textContent=fs.length?`${fs.length} files`:\"\";if(fs.error)return;if(!fs.length){l.innerHTML='<div class=\"py-8 text-center text-xs text-zinc-600\">No files yet</div>';return}l.innerHTML=fs.map((f,i)=>`<div class=\"flex items-center gap-3 px-3 py-2 rounded-lg hover:bg-white/[.02] transition-colors group\"><span class=\"text-sm\">\uD83D\uDCC4</span><div class=\"flex-1 min-w-0\"><div class=\"text-xs text-zinc-300 truncate\">${f.name}</div><div class=\"text-[10px] text-zinc-600\">${fmtSize(f.size)}</div></div><div class=\"hidden group-hover:flex gap-1\"><button onclick=\"downloadFile('${encodeURIComponent(f.name)}')\" class=\"text-zinc-500 hover:text-zinc-200 p-1 text-xs\">\u2193</button><button onclick=\"deleteFile('${encodeURIComponent(f.name)}')\" class=\"text-zinc-500 hover:text-red-400 p-1 text-xs\">\u00D7</button></div></div>`).join(\"\")}catch(e){}}function fmtSize(b){if(!b)return\"0B\";const u=[\"B\",\"KB\",\"MB\",\"GB\"];const i=Math.floor(Math.log(b)/Math.log(1024));return(b/Math.pow(1024,i)).toFixed(i?1:0)+\" \"+u[i]}\nasync function uploadFiles(fs){if(!fs?.length)return;const t=currentKB===\"all\"?(kbs[0]?.name||\"default\"):currentKB;if(!t)return;const fd=new FormData();for(const f of fs)fd.append(\"files\",f);try{await fetch(`/api/kb/${encodeURIComponent(t)}/upload`,{method:\"POST\",body:fd});await loadFiles()}catch(e){alert(e.message)}}\nfunction downloadFile(f){const t=currentKB===\"all\"?(kbs[0]?.name||\"default\"):currentKB;window.open(`/api/kb/${encodeURIComponent(t)}/files/${f}`,\"_blank\")}\nasync function deleteFile(f){if(!confirm(`Delete ${decodeURIComponent(f)}?`))return;const t=currentKB===\"all\"?(kbs[0]?.name||\"default\"):currentKB;try{await fetch(`/api/kb/${encodeURIComponent(t)}/files/${f}`,{method:\"DELETE\"});await loadFiles()}catch(e){alert(e.message)}}\nasync function sendMessage(){const inp=document.getElementById(\"chatInput\"),msg=inp.value.trim();if(!msg)return;inp.value=\"\";const msgs=document.getElementById(\"messages\");msgs.innerHTML+=`<div class=\"flex justify-end\"><div class=\"msg-user max-w-[75%] px-5 py-3 rounded-2xl rounded-br-md text-sm text-white leading-relaxed shadow-lg shadow-indigo-500/10\">${h(msg)}</div></div><div class=\"flex gap-3\"><div class=\"w-7 h-7 rounded-full bg-white/[.04] flex items-center justify-center text-xs shrink-0 mt-0.5\">AI</div><div class=\"text-sm text-zinc-500 py-2\">Thinking\u2026</div></div>`;msgs.scrollTop=msgs.scrollHeight;try{const r=await fetch(\"/api/chat\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({message:msg,kbName:currentKB===\"all\"?null:currentKB})}),d=await r.json();const el=msgs.lastElementChild;el&&el.remove();let html=`<div class=\"flex gap-3\"><div class=\"w-7 h-7 rounded-full bg-gradient-to-br from-indigo-500 to-purple-500 flex items-center justify-center text-[10px] text-white shrink-0 mt-0.5\">AK</div><div class=\"max-w-[75%]\"><div class=\"text-sm text-zinc-200 leading-relaxed\">${h(d.answer).replace(/\\n/g,\"<br>\")}</div>`;if(d.sources?.length){html+=`<div class=\"mt-3 flex flex-wrap gap-1.5\">${[...new Set(d.sources.map(s=>s.file))].map(f=>`<a href=\"/api/kb/${encodeURIComponent(currentKB===\"all\"?(kbs[0]?.name||\"default\"):currentKB)}/files/${encodeURIComponent(f)}\" target=\"_blank\" class=\"text-[11px] text-zinc-500 hover:text-indigo-400 no-underline px-2 py-0.5 rounded-md bg-white/[.03] border border-[#1a1a1d] transition-colors\">${f}</a>`).join(\"\")}</div>`}html+=\"</div></div>\";msgs.innerHTML+=html}catch(e){const el=msgs.lastElementChild;el&&el.remove();msgs.innerHTML+=`<div class=\"flex gap-3\"><div class=\"w-7 h-7 rounded-full bg-red-500/20 flex items-center justify-center text-xs text-red-400 shrink-0\">!</div><div class=\"text-sm text-red-400 py-2\">${h(e.message)}</div></div>`}msgs.scrollTop=msgs.scrollHeight}\nfunction h(s){return s.replace(/&/g,\"&amp;\").replace(/</g,\"&lt;\").replace(/>/g,\"&gt;\")}\nasync function loadConfig(){try{const r=await fetch(\"/api/config\"),c=await r.json();document.getElementById(\"cfgEmbedding\").innerHTML=buildCfg(\"embedding\",c.embedding);document.getElementById(\"cfgReranker\").innerHTML=buildCfg(\"reranker\",c.reranker);document.getElementById(\"cfgVLM\").innerHTML=buildCfg(\"videoSummarizer\",c.videoSummarizer||{});document.getElementById(\"cfgLLM\").innerHTML=buildCfg(\"llm\",c.providers?.llm||{})}catch(e){}}\nfunction buildCfg(prefix,obj){if(!obj)return'<div class=\"text-zinc-600 text-sm\">Not configured</div>';return Object.entries(obj).filter(([k])=>k!==\"api\"&&typeof obj[k]!==\"object\").map(([k,v])=>`<div class=\"flex items-center gap-4 mb-3\"><label class=\"w-32 text-right text-xs text-zinc-500 shrink-0\">${k}</label><input id=\"cfg_${prefix}_${k}\" value=\"${v||\"\"}\" class=\"flex-1 bg-[#0a0a0b] border border-[#2a2a2e] rounded-lg px-3 py-2 text-sm text-zinc-300 font-mono placeholder:text-zinc-700\"></div>`).join(\"\")}\nasync function saveConfig(){const u={};document.querySelectorAll(\"[id^=cfg_]\").forEach(i=>{const[,p,k]=i.id.split(\"_\");u[p]=u[p]||{};u[p][k]=i.value});try{await fetch(\"/api/config\",{method:\"PUT\",body:JSON.stringify(u),headers:{\"Content-Type\":\"application/json\"}});alert(\"Saved\")}catch(e){alert(\"Failed: \"+e.message)}}\nasync function loadLogs(){try{const r=await fetch(\"/api/logs?limit=300\"),logs=await r.json();document.getElementById(\"logContent\").textContent=logs.join(\"\\n\")||\"No logs yet\"}catch(e){}}\nloadKBs();loadFiles();\nconst fd=document.getElementById(\"fileDrop\");fd.addEventListener(\"dragover\",e=>{e.preventDefault();fd.style.borderColor=\"rgba(99,102,241,.4)\"});fd.addEventListener(\"dragleave\",()=>fd.style.borderColor=\"\");fd.addEventListener(\"drop\",e=>{e.preventDefault();fd.style.borderColor=\"\";uploadFiles(e.dataTransfer.files)});\n</script>\n</body>\n</html>\n";
